import { useContext } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import { useNavigate } from "react-router-dom";
import "../styles/global.css";

function Dashboard() {
  const { complaints } = useContext(ComplaintContext);
  const navigate = useNavigate();

  const departments = [
    {
      name: "Public Works",
      icon: "🏗️",
      sub: ["Road damage","Street light","Garbage","Bridge issue","Footpath"],
    },
    {
      name: "Water & Sanitation",
      icon: "💧",
      sub: ["Water leakage","Drainage","Sewage","Low pressure","Water supply"],
    },
    {
      name: "Health & Safety",
      icon: "🏥",
      sub: ["Hospital issue","Mosquito","Emergency","Food safety","Ambulance"],
    },
    {
      name: "Electricity",
      icon: "⚡",
      sub: ["Power cut","Transformer","Billing","Loose wire","Voltage issue"],
    },
    {
      name: "Transport",
      icon: "🚌",
      sub: ["Bus delay","Traffic signal","Accident","Parking","Road blockage"],
    },
    {
      name: "Environment",
      icon: "🌳",
      sub: ["Tree fall","Air pollution","Noise","Illegal dumping"],
    },
  ];

  const getCount = (dept) =>
    complaints.filter((c) => c.department === dept).length;

  /* ⭐ ripple click animation */
  const ripple = (e) => {
    const card = e.currentTarget;
    const circle = document.createElement("span");
    circle.className = "ripple";

    const rect = card.getBoundingClientRect();
    circle.style.left = `${e.clientX - rect.left}px`;
    circle.style.top = `${e.clientY - rect.top}px`;

    card.appendChild(circle);
    setTimeout(() => circle.remove(), 600);
  };

  return (
    <div className="dashboard-page animated-bg">
      {/* ⭐ HEADER */}
      <div className="citizen-header">
  <div>
    <h2>Citizen's Voice</h2>
    <p>Choose department & file complaint</p>
  </div>

  <div className="header-right">
    <div
      className="status-bar"
      onClick={() => navigate("/track")}
    >
      📋 View Application Status
    </div>
  </div>
</div>

      {/* ⭐ GRID */}
      <div className="dept-grid">
        {departments.map((d) => (
          <div
            key={d.name}
            className="dept-card"
            onClick={(e) => {
              ripple(e);
              navigate("/add", {
                state: { department: d.name, categories: d.sub },
              });
            }}
          >
            <div className="badge">{getCount(d.name)}</div>
            <div className="icon">{d.icon}</div>
            <h3>{d.name}</h3>
            <p>Click to file complaint</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Dashboard;
